SELECT COUNT(*) FROM "title" AS v1, "infoVertex" AS v2, "infoIdxVertex" AS v3, "title_infoEdge_infoVertex" AS e1, "title_infoEdge_infoIdxVertex" AS e2, "title_movieCompanies_companyName" AS e3 WHERE e1.src = v1.id AND e1.dst = v2.id AND e2.src = v1.id AND e2.dst = v3.id AND e3.src = v1.id AND v3."info_type_id" = 101 AND v2."info_type_id" = 3 AND v1."production_year" > 2005 AND v1."production_year" < 2008 AND e3."company_type_id" = 2;
